CREATE OR REPLACE FUNCTION safebus_private.enforce_active_api_session()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_path text := ltrim(current_setting('request.path', true), '/');
  v_method text := current_setting('request.method', true);
begin
  if auth.role() = 'service_role' then return; end if;
  if v_path = 'rpc/is_current_user_session_active'
     and v_method in ('GET', 'HEAD', 'POST') then return; end if;
  if not public.is_current_user_session_active() then
    raise exception 'An active SafeBus session is required.' using errcode = '42501';
  end if;
  if safebus_private.has_completed_optional_mfa() then return; end if;
  if v_path = 'profiles' and v_method in ('GET', 'HEAD') then return; end if;
  if v_path in ('rpc/register_current_user_session', 'rpc/record_own_auth_event')
     and v_method = 'POST' then return; end if;
  raise exception 'Complete multi-factor authentication to continue.' using errcode = '42501';
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_invited_account()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_password_hash text;
begin
  if auth.uid() is null then
    raise exception 'Sign in through a valid invitation before completing account setup.'
      using errcode = '42501';
  end if;

  select * into v_profile from public.profiles where id = auth.uid() for update;
  if v_profile.id is null then
    raise exception 'The invited SafeBus profile was not found.' using errcode = 'P0002';
  end if;
  if v_profile.status = 'active' then
    return jsonb_build_object('profileId', v_profile.id, 'role', v_profile.role, 'status', 'active');
  end if;
  if v_profile.status <> 'invited' then
    raise exception 'This SafeBus account is not available for invitation setup.' using errcode = '22023';
  end if;
  if v_profile.role <> 'platform_super_admin' and not exists (
    select 1 from public.tenants t where t.id = v_profile.tenant_id and t.status = 'active'
  ) then
    raise exception 'This SafeBus organization is not active.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.tenant_onboarding_invitations i
    where i.invited_profile_id = auth.uid()
      and i.status in ('pending', 'resent')
      and i.expires_at > now()
  ) then
    raise exception 'This invitation is expired, revoked, cancelled, or no longer valid.'
      using errcode = '22023';
  end if;

  select u.encrypted_password into v_password_hash
  from auth.users u
  where u.id = auth.uid() and u.email_confirmed_at is not null;
  if nullif(v_password_hash, '') is null then
    raise exception 'Create a password before completing account setup.' using errcode = '22023';
  end if;

  update public.profiles set status = 'active'
  where id = auth.uid() and status = 'invited';
  update public.tenant_onboarding_invitations
  set status = 'activated', cancelled_at = null,
      delivery_status = case when delivery_status in ('pending', 'processing') then 'sent' else delivery_status end
  where invited_profile_id = auth.uid()
    and status in ('pending', 'resent') and expires_at > now();

  return jsonb_build_object('profileId', v_profile.id, 'role', v_profile.role, 'status', 'active');
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_new_password_policy(p_password text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Authentication is required to change a password.' using errcode = '42501';
  end if;
  if not safebus_private.validate_password_policy(p_password) then
    raise exception 'Password does not meet the SafeBus password policy.' using errcode = '22023';
  end if;
  if safebus_private.is_compromised_password(p_password) then
    raise exception 'Choose a password that is not present in the compromised-password list.' using errcode = '22023';
  end if;
end;
$function$
